  createAAProviderState,
  type AAMode,
  type AAProvider,
} from "@aomi-labs/client";
import { toClientAAOwner, type AomiAAOwnerInput } from "../../aa/owner";
import type { AomiAuthIdentity } from "../../types";
import {
  getPreferredRpcUrl,
  type RequestedAAMode,
