export type WagmiAccountShape = {
  address?: `0x${string}`;
  chainId?: number;
  isConnected: boolean;
  connector?: { id?: string; name?: string; type?: string; uid?: string };
};

export type WagmiConfigShape = {
  chains: readonly Chain[];
  connectors: readonly Connector[];
};

const DISCONNECTED_WAGMI_ACCOUNT: WagmiAccountShape = {
  address: undefined,
  chainId: undefined,
  isConnected: false,
};

const DISCONNECTED_WAGMI_CONFIG: WagmiConfigShape = {
  chains: [],
  connectors: [],
};

export function useSafeWagmiAccount(): WagmiAccountShape {
  try {
    return useAccount() as WagmiAccountShape;
  } catch {
    return DISCONNECTED_WAGMI_ACCOUNT;
  }
}

export function useSafeWalletClient(): {
  walletClient?: ReturnType<typeof useWalletClient>["data"];
} {
  try {
    const { data } = useWalletClient();
    return { walletClient: data };
  } catch {
    return { walletClient: undefined };
  }
}

export function useSafeGetWalletClientFor(): (args: {
  connector?: Connector;
  chainId?: number;
}) => Promise<ReturnType<typeof useWalletClient>["data"] | null> {
  try {
    const config = useConfig();
    return async ({ connector, chainId }) => {
      if (!connector) return null;
      try {
        return await getWalletClient(config, { connector, chainId } as never);
      } catch (error) {
        walletDebug("aa:wallet-client-failed", {
          connector: connector.id,
          chainId,
          error: error instanceof Error ? error.message : String(error),
        });
        return null;
      }
